from taf.nms.nom.schemas.base import SchemaObject, SchemaField


class ConfigurationPostPlanResponseInfo(SchemaObject):
    conf_id = SchemaField(name="conf_id")
    description = SchemaField(name="description")
    name = SchemaField(name="name")

    def __init__(self, conf_id, description, name):
        self.conf_id = conf_id
        self.description = description
        self.name = name
        super(ConfigurationPostPlanResponseInfo, self).__init__()
